//! Python (`re` / `str`) character classes, Unicode 16.0 as shipped with Python 3.14.
//!
//! Python's `\s`, `\w` and `str.isprintable()` do not coincide with the Unicode
//! properties Rust's standard library exposes (e.g. `\s` includes `U+001C..U+001F`,
//! `\w` excludes combining marks). Upstream behaviour depends on them, so the word
//! and printable classes are embedded as range tables (generated by
//! `tools/gen_f2b_helpers_fixtures.py` from the real interpreter).

include!("pyunicode_tables.rs");

/// `re` `\s` (and `str.isspace()`) for a `str` pattern.
pub fn is_space(c: char) -> bool {
    matches!(
        c,
        '\t'..='\r'
            | '\x1c'..='\x1f'
            | ' '
            | '\u{85}'
            | '\u{a0}'
            | '\u{1680}'
            | '\u{2000}'..='\u{200a}'
            | '\u{2028}'
            | '\u{2029}'
            | '\u{202f}'
            | '\u{205f}'
            | '\u{3000}'
    )
}

fn in_ranges(table: &[(u32, u32)], c: char) -> bool {
    let c = u32::from(c);
    let i = table.partition_point(|&(_, hi)| hi < c);
    table.get(i).is_some_and(|&(lo, _)| lo <= c)
}

/// `re` `\w` for a `str` pattern.
pub fn is_word(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphanumeric() || c == '_';
    }
    in_ranges(WORD_RANGES, c)
}

/// `str.isprintable()` for a single character.
pub fn is_printable(c: char) -> bool {
    if c.is_ascii() {
        return (' '..='~').contains(&c);
    }
    !in_ranges(NONPRINTABLE_RANGES, c)
}

/// `str.strip()` (no arguments) for both ends.
pub fn strip(s: &str) -> &str {
    s.trim_matches(is_space)
}

/// Python `repr()` of a `str`.
pub fn repr_str(s: &str) -> String {
    use std::fmt::Write;
    let quote = if s.contains('\'') && !s.contains('"') {
        '"'
    } else {
        '\''
    };
    let mut out = String::with_capacity(s.len() + 2);
    out.push(quote);
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            c if c == quote => {
                out.push('\\');
                out.push(c);
            }
            c if is_printable(c) => out.push(c),
            c => {
                let n = u32::from(c);
                let _ = if n <= 0xff {
                    write!(out, "\\x{n:02x}")
                } else if n <= 0xffff {
                    write!(out, "\\u{n:04x}")
                } else {
                    write!(out, "\\U{n:08x}")
                };
            }
        }
    }
    out.push(quote);
    out
}
